INSERT INTO pyq_collections (id, slug, subject, title, exam_paper, year, is_premium, question_count, sort_order)
VALUES ('26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 'upsc-anthropology-optional-paper-1-pyq', 'anthropology', 'UPSC Anthropology Optional Paper I — PYQ & Model Answers (2023)', 'paper-1', 2023, true, 28, 1);

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('0b79c019-f67b-4e14-92e7-6346bd82045d', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 1, 'A', '1(a)', 10, 150, 'Scope and relevance of Social and Cultural Anthropology');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('0b79c019-f67b-4e14-92e7-6346bd82045d', 'Social and Cultural Anthropology studies human societies and cultures holistically -- kinship, economy, politics, religion, language and material life -- through fieldwork-based, comparative and cross-cultural method (Malinowski''s participant observation, Radcliffe-Brown''s structural-functionalism, Boas''s cultural relativism).

Scope: covers pre-literate/tribal societies (its classical focus), peasant and complex urban societies (post-1950s expansion), and today''s globalized, digital and diasporic communities -- studying institutions (marriage, family, descent), belief systems, economic organization, and processes of change (Sanskritization, modernization, globalization).

Relevance today: informs tribal welfare and PVTG policy, guides culturally-sensitive public-health and development interventions, underlies ethnographic evaluation of government schemes, and contributes to debates on identity, multiculturalism and indigenous rights. Applied/development anthropology (medical, visual, urban, business anthropology) demonstrates its continuing practical relevance beyond pure academic description, making it indispensable for policy grounded in lived cultural reality rather than abstract universalism.', 'Should move beyond dictionary-definition to name specific theoretical schools (Boas, Malinowski, Radcliffe-Brown) and at least one contemporary applied-anthropology relevance point (tribal policy, public health) to earn full marks in 150 words.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q1(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c6043733-7ea8-4812-bb46-7a6541256283', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 2, 'A', '1(b)', 10, 150, 'Cultural impact of Iron Age');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c6043733-7ea8-4812-bb46-7a6541256283', 'The Iron Age (in India, roughly 1500-200 BCE, following the Chalcolithic) marked a decisive technological and cultural transition driven by iron smelting and tool/weapon production.

Cultural impacts: (i) agricultural expansion -- iron ploughshares and axes enabled forest clearance and cultivation of harder, previously unworkable soils (Ganga plains), supporting population growth and settled village life; (ii) surplus and social stratification -- higher agricultural productivity generated surplus enabling craft specialization, trade and emergent elites, laying groundwork for state formation (Painted Grey Ware culture, associated with later Vedic society); (iii) military transformation -- iron weapons changed warfare and political consolidation, contributing to the rise of the Mahajanapadas; (iv) craft and exchange networks -- ironsmithing as a specialized occupation fostered artisan guilds and long-distance trade. Archaeologically, sites like Hallur, Naikund and various megalithic burial complexes in peninsular India show iron tools alongside distinct megalithic mortuary practices, indicating that Iron Age culture was not uniform but regionally variable across the subcontinent.', 'Expected to connect the purely technological fact (iron smelting) to social consequences -- agriculture, stratification, state formation -- rather than a bare metallurgy description; naming at least one Indian site/culture (Painted Grey Ware, megalithic peninsular sites) strengthens the answer.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q1(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('1e4b9eec-bd7f-46f3-a24a-23ac2174ffa4', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 3, 'A', '1(c)', 10, 150, 'Race and Ethnicity');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('1e4b9eec-bd7f-46f3-a24a-23ac2174ffa4', 'Race is a now largely discredited biological classification of humans based on superficial phenotypic traits (skin colour, hair form, cranial index) once believed to correlate with discrete, hereditary sub-species; modern genetics (Lewontin''s finding that ~85% of human genetic variation occurs within, not between, so-called races) has shown race lacks a valid biological basis and is better understood as a socially constructed category with real social consequences (racism, discrimination).

Ethnicity, by contrast, is a socio-cultural category -- a group''s self-identification based on shared ancestry, language, religion, customs and historical memory (Max Weber; Fredrik Barth''s boundary-maintenance approach), which can shift situationally and is not tied to biology.

Distinction: race claims biological grounding (now rejected), ethnicity is explicitly cultural/subjective. Both, however, have been used historically to justify discrimination and hierarchy (colonial racial classification of Indian tribes/castes by Risley), making a critical anthropological understanding of both concepts essential to combating essentialist and discriminatory ideologies.', 'Must explicitly state that biological race has been scientifically discredited (Lewontin) while distinguishing it from the sociological/self-identified nature of ethnicity (Barth); an Indian colonial-classification example (Risley) is a useful concrete anchor.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q1(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b120080a-ddf4-4acc-aeb3-85c8ac19c156', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 4, 'A', '1(d)', 10, 150, 'Customary laws and Environmental conservation');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b120080a-ddf4-4acc-aeb3-85c8ac19c156', 'Customary laws -- unwritten, community-sanctioned norms governing resource use, inheritance and dispute resolution among tribal and traditional societies -- have historically embedded strong environmental-conservation logic, since community survival depended directly on sustainable resource use.

Examples: sacred groves (devrai/sarna/law kyntang) protected by taboo among Warli, Munda, Khasi and other communities preserve biodiversity through religious sanction rather than formal ecology; totemic clan restrictions among Gonds and Santhals prohibit hunting/harming specific species; shifting-cultivation (jhum) cycles among Northeast tribes traditionally included fallow periods regulated by customary norms to allow forest regeneration; water-sharing and grazing-rotation customs prevent resource depletion in arid regions (Rajasthan''s Bishnoi community, famous for tree/wildlife protection under Guru Jambheshwar''s customary teachings).

Significance: the Forest Rights Act, 2006 and Panchayats (Extension to Scheduled Areas) Act, 1996 have begun formally recognizing such customary community-conservation practices, reflecting growing policy acknowledgment that customary law-based conservation often outperforms externally-imposed regulation in ensuring long-term ecological sustainability.', 'Naming specific ethnographic examples (Bishnoi, sacred groves, jhum fallow cycles) rather than a generic ''tribes protect nature'' claim is essential; linking to the Forest Rights Act as formal legal recognition earns additional credit.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q1(d). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c9f85703-cd3e-4cc4-b8c5-32a71a468ab6', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 5, 'A', '1(e)', 10, 150, 'Gene expression');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c9f85703-cd3e-4cc4-b8c5-32a71a468ab6', 'Gene expression is the process by which information encoded in a gene (DNA) is used to synthesize a functional product, typically a protein, via transcription (DNA to mRNA) and translation (mRNA to protein), regulated at multiple levels (transcriptional, post-transcriptional, translational, epigenetic).

Regulation: not all genes are expressed at all times -- transcription factors, promoters/enhancers, and epigenetic modifications (DNA methylation, histone modification) switch genes on or off in a tissue- and stage-specific manner, explaining how a single genome produces diverse cell types.

Anthropological relevance: gene expression underlies human variation and adaptation -- e.g., lactase persistence (continued expression of the LCT gene into adulthood) evolved independently in pastoralist populations (Northern Europeans, some East African groups) as a genetic-cultural coevolution response to dairying; high-altitude Tibetan and Andean populations show distinct EPAS1/genetic-expression adaptations to hypoxia. Gene-environment interaction (epigenetics) is thus central to physical/biological anthropology''s understanding of human adaptability, linking molecular biology directly to population-level cultural and ecological history.', 'A biology-only answer (transcription/translation mechanics) without an anthropological application (lactase persistence, high-altitude adaptation) will be marked incomplete for this optional; both halves are expected.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q1(e). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('7859acbd-c6b2-4bd7-b552-80cf0f20769b', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 6, 'A', '2(a)', 20, 350, 'Discuss major species of Australopithecus discovered from South and East Africa. Describe the discovery, physical features and significance of Taung baby.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('7859acbd-c6b2-4bd7-b552-80cf0f20769b', 'Introduction: Australopithecus, a genus of early bipedal hominins living roughly 4-2 million years ago in Africa, is central to understanding the transition from ape-like ancestors to genus Homo.

Major South African species: Australopithecus africanus (Sterkfontein, Taung, Makapansgat) -- gracile form, smaller teeth, more human-like cranial features than robust forms; Australopithecus robustus/Paranthropus robustus (Swartkrans, Kromdraai) -- robust masticatory apparatus, large molars and sagittal crest adapted to hard, fibrous diet.

Major East African species: Australopithecus afarensis (Hadar, Laetoli; ''Lucy'' skeleton, Laetoli footprints) -- clear bipedalism with small brain (~400-500cc), long arms retaining some arboreal adaptation; Australopithecus anamensis (earlier, more primitive, Kenya); Paranthropus boisei/aethiopicus (East African robust lineage, ''Nutcracker Man'', massive cheek teeth).

Taung baby: discovered by Raymond Dart in 1924 at Taung, South Africa -- a juvenile skull (endocast plus facial fragments) that Dart named Australopithecus africanus. Physical features: foramen magnum positioned forward (beneath the skull rather than at the rear as in apes), indicating upright bipedal posture; brain endocast showing human-like convolution patterns despite small size; dentition intermediate between ape and human.

Significance: Taung baby was the first australopithecine fossil discovered and the first strong fossil evidence that bipedalism preceded large brain size in human evolution -- directly contradicting the then-dominant ''brain-first'' theory (which wrongly expected a large-brained ancestor, as seemingly supported by the Piltdown hoax). Dart''s identification was initially rejected by the European scientific establishment due to racial/geographic bias favouring Asia or Europe as the cradle of humanity, and was vindicated only decades later with further African discoveries (Broom''s robust australopithecines, the Leakeys'' East African finds), establishing Africa as humanity''s evolutionary homeland.

Conclusion: the South African gracile/robust and East African afarensis/boisei lineages together map Australopithecus''s adaptive radiation, while Taung baby''s rediscovery-and-vindication story remains a landmark in establishing bipedalism''s evolutionary priority over encephalization.', 'Must name specific fossil sites and species (not a generic ''early hominins'' answer), explicitly state the foramen magnum evidence for bipedalism in Taung baby, and connect its significance to disproving the ''brain-first'' hypothesis (contra Piltdown) -- this causal argument is the core expected content.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q2(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('657e32c0-b8de-4544-94d1-f7150e549c92', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 7, 'A', '2(b)', 15, 250, 'Discuss the Paleolithic environment in light of available evidences with special reference to India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('657e32c0-b8de-4544-94d1-f7150e549c92', 'The Paleolithic (Old Stone Age, in India roughly 2.6 million-10,000 years ago, subdivided into Lower/Middle/Upper) coincided with the Pleistocene''s fluctuating glacial-interglacial climate, shaping tool technology, subsistence and settlement.

Evidence types: geological/stratigraphic sequences (river-terrace deposits at Narmada, Son and Soan valleys), faunal remains (fossil fauna indicating climate at a given layer), pollen analysis, and lithic typology correlated with climatic phases.

Indian evidence: Lower Paleolithic Acheulian sites (Hunsgi-Baichbal in Karnataka, Bhimbetka in Madhya Pradesh, Attirampakkam in Tamil Nadu) show hand-axes and cleavers associated with relatively wetter, savanna-woodland conditions supporting big-game hunting/scavenging. Middle Paleolithic sites (Site 55 in the Son Valley, Bhimbetka) show flake-based tools coinciding with more arid phases. The Toba super-eruption (~74,000 years ago, ash layer found across the subcontinent, e.g., at Jwalapuram in Andhra Pradesh) is a key stratigraphic marker debated for its climatic-demographic impact on Paleolithic populations in India -- some researchers argue continuity of tool traditions across the ash layer at Jwalapuram, challenging a severe ''volcanic winter'' population-bottleneck hypothesis.

Upper Paleolithic sites (Bhimbetka''s rock shelters, Patne in Maharashtra) show blade/burin technology associated with the last glacial period''s cooler, drier climate.

Conclusion: India''s Paleolithic record, anchored in river-valley stratigraphy and the Toba ash marker, demonstrates a close, evidence-based relationship between shifting Pleistocene environments and successive lithic-technological adaptations.', 'Naming specific Indian sites (Bhimbetka, Hunsgi-Baichbal, Attirampakkam, Jwalapuram) and the Toba ash-layer debate is the expected substantive content distinguishing a strong answer from a generic global Paleolithic-climate description.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q2(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('3ee6ab3b-5326-48ea-ad69-fc96d05ace76', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 8, 'A', '2(c)', 15, 250, 'Elucidate the different forms of malnutrition. Describe protein-calorie malnutrition with suitable examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('3ee6ab3b-5326-48ea-ad69-fc96d05ace76', 'Malnutrition denotes deficiencies, excesses or imbalances in nutrient intake, broadly classified into undernutrition (protein-calorie malnutrition, micronutrient deficiencies) and overnutrition (obesity, diet-related non-communicable diseases).

Forms: (i) Protein-Calorie/Protein-Energy Malnutrition (PCM/PEM) -- inadequate protein and/or calorie intake, most severe in children; (ii) micronutrient malnutrition -- deficiencies of iron (anaemia), iodine (goitre, cretinism), Vitamin A (xerophthalmia, night blindness), zinc; (iii) overnutrition -- excessive caloric intake causing obesity, type-2 diabetes, cardiovascular disease, increasingly significant in India''s nutrition-transition context alongside persistent undernutrition (''double burden of malnutrition'').

Protein-calorie malnutrition in detail: two classical clinical presentations -- Kwashiorkor (adequate calories but severe protein deficiency; oedema, distended belly, hair depigmentation, apathy, first described among West African weanling children) and Marasmus (severe deficiency of both protein and calories; extreme wasting, ''skin and bones'' appearance, more common in infants under one year). Marasmic-kwashiorkor is a mixed intermediate form. Anthropometric indicators (weight-for-age, height-for-age/stunting, weight-for-height/wasting, per WHO/NFHS classifications) are used to assess PCM prevalence -- India''s NFHS-5 data shows persistently high childhood stunting and wasting rates despite economic growth, reflecting PCM''s continued public-health significance, particularly among tribal and economically marginalized populations studied extensively in nutritional/physical anthropology.', 'Kwashiorkor vs Marasmus must be explicitly distinguished with their characteristic clinical signs; citing NFHS stunting/wasting data situates the answer in the Indian public-health-anthropology context expected of this optional.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q2(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c1500e90-e416-4ce3-9bf8-b6a5aa33f432', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 9, 'A', '3(a)', 20, 350, 'What is hominization process? Discuss the major trends in human evolution with the help of suitable examples and illustrations.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c1500e90-e416-4ce3-9bf8-b6a5aa33f432', 'Introduction: hominization is the evolutionary process by which ape-like ancestors progressively acquired the distinctive anatomical, behavioural and cognitive traits characterizing modern Homo sapiens, unfolding over roughly 6-7 million years since the human-chimpanzee divergence.

Major trends: (i) Bipedalism -- earliest and most fundamental trend, evident in Sahelanthropus/Orrorin/Ardipithecus and confirmed in Australopithecus afarensis (Lucy, Laetoli footprints), freeing hands for tool use and carrying, and preceding brain enlargement; (ii) Encephalization -- progressive brain-size increase from ~400-500cc in australopithecines to ~600-700cc in early Homo (Homo habilis), ~900-1100cc in Homo erectus, and ~1350cc average in Homo sapiens, associated with increasing behavioural complexity; (iii) Dental reduction -- reduction in canine size and molar/jaw robustness from ape-like dentition toward smaller, more generalized human teeth, linked to dietary and tool-use changes (cooking, food processing); (iv) Tool-making/culture -- from Oldowan pebble tools (Homo habilis, ~2.6 mya) to Acheulian hand-axes (Homo erectus) to Mousterian/Upper Paleolithic blade and symbolic technology (Homo sapiens/Neanderthals), reflecting growing cognitive and cultural capacity; (v) Facial and cranial changes -- reduction of prognathism (facial protrusion), development of a chin (unique to Homo sapiens), rounding of the braincase; (vi) Life-history changes -- extended childhood/juvenile dependency period allowing prolonged learning, correlated with brain development; (vii) Language and symbolic behaviour -- emergence of symbolic art, burial practices and complex social organization, especially from the Upper Paleolithic onward (Blombos Cave ochre engravings, European cave art).

Illustrative sequence: Ardipithecus ramidus (facultative bipedalism) to Australopithecus afarensis (obligate bipedalism, small brain) to Homo habilis (tool use, modest brain increase) to Homo erectus (further encephalization, fire use, migration out of Africa) to Homo sapiens (full modern anatomy, symbolic culture).

Conclusion: hominization was not a single linear trend but a mosaic evolution in which bipedalism, encephalization, dental reduction, tool-making and extended life-history combined -- at different rates in different lineages -- to eventually produce anatomically and behaviourally modern humans.', 'The ''mosaic evolution'' framing (traits evolving at different rates, not a single ladder) is the key conceptual point expected; a strong answer sequences specific genera/fossils (Ardipithecus to Australopithecus to Homo habilis/erectus/sapiens) against each named trend rather than listing trends abstractly.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q3(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('df8177a5-893e-4c74-9bdf-fee0dfdfb391', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 10, 'A', '3(b)', 15, 250, 'How did Clifford Geertz look at religion? Differentiate between anthropological and psychological approaches to the study of religion.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('df8177a5-893e-4c74-9bdf-fee0dfdfb391', 'Clifford Geertz, in his influential essay ''Religion as a Cultural System'' (1966), defined religion as: ''(1) a system of symbols which acts to (2) establish powerful, pervasive, and long-lasting moods and motivations in men by (3) formulating conceptions of a general order of existence and (4) clothing these conceptions with such an aura of factuality that (5) the moods and motivations seem uniquely realistic.'' For Geertz, religion functions as a cultural system providing both a ''model of'' reality (an interpretive worldview explaining existence) and a ''model for'' reality (a normative guide shaping behaviour and ethos), synthesizing a people''s ethos (moral/aesthetic style) with their worldview (cognitive picture of order) via sacred symbols. His method emphasized ''thick description'' -- interpreting religious symbols and rituals within their specific cultural context rather than seeking universal psychological or biological explanations.

Anthropological vs psychological approaches: the anthropological approach (Geertz, Durkheim, Turner) treats religion as a social/cultural phenomenon -- studying symbols, rituals and collective meaning-making embedded in specific societies through fieldwork and comparative ethnography, emphasizing religion''s social function (integration, meaning, legitimation of order). The psychological approach (Freud''s projection theory viewing religion as wish-fulfillment/illusion, Jung''s collective-unconscious archetypes) instead locates religion''s origin and function within individual mental processes -- unconscious drives, anxiety-reduction, or universal archetypal symbols -- largely independent of specific cultural context.

Conclusion: Geertz''s symbolic-interpretive, culturally-embedded approach exemplifies anthropology''s contextual method, contrasting sharply with psychology''s universalizing, intra-psychic explanatory framework.', 'The five-part Geertz definition (or its substantive content) should be reproduced closely, and ''model of/model for'' terminology is a strong differentiator; the Freud/Jung contrast is the standard expected psychological comparison.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q3(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ccb90bb5-cdeb-4418-8d27-5f62b49e24d0', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 11, 'A', '3(c)', 15, 250, 'What is mixed-longitudinal method of studying human growth? Discuss its merits and demerits.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ccb90bb5-cdeb-4418-8d27-5f62b49e24d0', 'Human growth studies employ three basic designs: cross-sectional (different individuals of different ages measured once), longitudinal (the same individuals measured repeatedly over time), and mixed-longitudinal (a hybrid combining overlapping shorter longitudinal cohorts of different starting ages, staggered so their age-ranges overlap, to reconstruct a full growth curve faster than a single pure-longitudinal study would allow).

Mechanism: e.g., to study growth from age 0-18, several cohorts might be started simultaneously at ages 0, 6, 12, each followed for 6-8 years, with overlapping age-ranges used to statistically ''splice'' the segments into a single continuous growth curve.

Merits: (i) faster results than pure longitudinal design (which would require following a single cohort for the entire age range, e.g., 18 years); (ii) still captures genuine individual growth velocity and within-individual variation, unlike cross-sectional data; (iii) reduces attrition risk relative to a single long-duration cohort, since each sub-cohort is followed for a shorter period; (iv) allows earlier availability of preliminary growth-curve data for policy/clinical use.

Demerits: (i) statistical complexity in splicing overlapping cohorts, requiring careful methods to avoid cohort-effect bias (different cohorts may have experienced different nutritional/environmental conditions); (ii) still subject to some attrition within each sub-cohort; (iii) sample-size and comparability challenges when overlapping segments don''t align smoothly; (iv) cannot fully replace true longitudinal depth for studying individual growth trajectories across the entire span.

Conclusion: mixed-longitudinal design offers a practical, time-efficient compromise between cross-sectional breadth and longitudinal depth, widely used in auxological (human growth) research including Indian growth studies of tribal and school-going populations.', 'The answer must explain the ''overlapping staggered cohorts spliced together'' mechanism specifically, not merely define longitudinal vs cross-sectional in general; cohort-effect bias is the key demerit examiners look for.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q3(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('51e8bf71-21f1-42fb-8dfe-d51f44295e21', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 12, 'A', '4(a)', 20, 350, 'Discuss the role of marriage regulations in traditional societies in India for strengthening social solidarity.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('51e8bf71-21f1-42fb-8dfe-d51f44295e21', 'Introduction: marriage regulations in traditional Indian societies -- rules governing whom one may or must marry -- are not merely reproductive arrangements but function as central mechanisms binding kin groups, castes and communities into networks of mutual obligation, reinforcing social solidarity (in Durkheim''s sense of shared norms and interdependence).

Exogamy and alliance: clan/gotra exogamy (marrying outside one''s own clan) among most Hindu and tribal groups creates alliances between previously unrelated lineages, extending kinship networks and cooperation beyond the natal group -- Levi-Strauss''s alliance theory frames this as the ''exchange of women'' generating reciprocal obligations that bind society together more durably than descent alone.

Endogamy and caste solidarity: caste/sub-caste (jati) endogamy reinforces internal caste solidarity and identity, maintaining boundaries and internal cohesion while regulating status and purity concerns central to the varna-jati order; among many South Indian communities, cross-cousin and uncle-niece marriage preferences (mama-marumagal) keep property and alliance within a defined kin circle, strengthening intra-lineage bonds.

Tribal examples: bride-price/service (as among many Central Indian tribes like Gonds, Santhals) and reciprocal marriage exchanges (sister-exchange marriages) create durable inter-lineage alliances and mutual economic obligation; among the Khasi and Garo (matrilineal Northeast), marriage regulations tied to clan membership similarly structure inter-clan cooperation and property devolution.

Ritual and social functions: marriage ceremonies themselves are major occasions for kin-group mobilization, feasting and gift-exchange (jajmani-linked obligations), reaffirming community bonds; levirate and sororate customs (widow remarriage within the deceased spouse''s kin group) preserve alliance ties and provide social security functions.

Critical note: marriage regulations can also entrench hierarchy and restrict individual choice (caste endogamy underpinning caste rigidity, honour-based violence against inter-caste ''love marriages''), showing that the same rules securing solidarity within a group can simultaneously produce exclusion and conflict across group boundaries.

Conclusion: marriage regulations in India function as a structural mechanism generating both intra-group cohesion (endogamy) and inter-group alliance (exogamy), making them central -- if occasionally double-edged -- to traditional social solidarity.', 'Levi-Strauss''s alliance theory (exchange/exogamy generating inter-group bonds) alongside a concrete Indian tribal example (Gond/Santhal sister-exchange, Khasi/Garo matrilineal alliance) is the expected theoretical-plus-ethnographic combination; a purely descriptive answer without the alliance-theory lens will lose marks.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q4(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('5c7c2cf5-a704-4192-9913-13c4e171e8ae', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 13, 'A', '4(b)', 15, 250, 'Discuss various methods of personal identification based on skeletal remains.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('5c7c2cf5-a704-4192-9913-13c4e171e8ae', 'Forensic/physical anthropology uses skeletal evidence to establish the ''biological profile'' of unidentified remains -- sex, age, stature, ancestry and individualizing features.

Sex determination: pelvis is most reliable (wider sub-pubic angle, larger pelvic inlet, presence of a ventral arc/sub-pubic concavity in females); skull traits (robust brow ridges, mastoid processes, nuchal crest in males vs smoother/gracile features in females) are secondary indicators.

Age estimation: epiphyseal fusion patterns (long-bone growth plates fuse in known age sequences during childhood/adolescence); cranial suture closure in adults (though less reliable); pubic symphysis and auricular surface morphology (Todd''s/Suchey-Brooks methods) for adult age; dental development and wear patterns (Gustafson''s method) across the lifespan.

Stature estimation: regression formulae (Trotter-Gleser, and India-specific formulae developed for Indian populations) applying known mathematical ratios between long-bone length (femur, tibia, humerus) and living stature.

Ancestry/population affinity: cranial metric and non-metric traits (nasal aperture shape, cranial index, prognathism) compared against reference population data, though this method carries significant scientific limitations given race''s discredited biological basis.

Individualization: unique skeletal pathologies, healed fractures, dental records compared against ante-mortem records, and DNA profiling (mitochondrial DNA for degraded/old remains) provide the strongest individual-level identification, often used together with the biological profile in medico-legal and mass-disaster identification contexts in India.', 'The pelvis-based sex determination and epiphyseal-fusion/pubic-symphysis age methods are the two most commonly under-detailed areas -- naming specific named methods (Suchey-Brooks, Trotter-Gleser) signals depth expected at 15 marks.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q4(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ee6cdc58-499e-4f72-8e0d-313d9ca516b1', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 14, 'A', '4(c)', 15, 250, 'Identify the major Mesolithic sites and describe the typo-technological features with special reference to India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ee6cdc58-499e-4f72-8e0d-313d9ca516b1', 'The Mesolithic (in India roughly 10,000-4,000 years ago) bridges the Paleolithic and Neolithic, associated with post-glacial climatic amelioration, forest/grassland expansion, and a shift toward broad-spectrum foraging.

Major Indian sites: Bagor (Rajasthan, on the Kothari river) -- one of the most extensively excavated, with evidence of microliths, animal domestication (sheep/goat) and burial practices; Langhnaj (Gujarat) -- microliths alongside faunal and human skeletal remains; Sarai Nahar Rai and Mahadaha (Uttar Pradesh, Ganga plain) -- rich microlithic assemblages with associated burials showing grave goods; Adamgarh (Madhya Pradesh) -- early evidence of possible animal domestication; Bhimbetka rock shelters (Madhya Pradesh) -- continuous Mesolithic occupation with rock art depicting hunting scenes; Tilwara (Rajasthan) and Chopani-Mando (Uttar Pradesh, Belan valley) -- transitional Mesolithic-to-Neolithic sequences.

Typo-technological features: dominant tool type is the microlith -- small (typically under 5cm), geometric (triangles, trapezes, lunates/crescents, points) stone tools made primarily on blades struck from prepared cores using the pressure-flaking and blade technique, often hafted into composite tools (arrows, sickles, harpoons) using bone/wood/resin. This represents a technological shift from the larger core-tools of the Paleolithic toward smaller, more efficient, specialized composite tools suited to hunting smaller, faster fauna in the post-glacial environment, and toward the diversified subsistence base (hunting, fishing, plant gathering) that eventually supported the Neolithic transition to agriculture.

Conclusion: India''s Mesolithic sites collectively document the microlithic technological revolution and the broad-spectrum subsistence adaptation that set the stage for Neolithic domestication.', 'Must name multiple specific sites (Bagor, Langhnaj, Sarai Nahar Rai/Mahadaha, Bhimbetka) across different Indian regions and explicitly describe microlith typology (geometric forms, hafting into composite tools) as the defining typo-technological feature.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section A, Q4(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('52bab31d-fc06-4d61-9cdc-eaedd91ebcc6', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 15, 'B', '5(a)', 10, 150, 'Polygenic Inheritance');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('52bab31d-fc06-4d61-9cdc-eaedd91ebcc6', 'Polygenic inheritance refers to traits controlled by the cumulative, additive effect of multiple genes (often at different loci), each contributing a small effect, rather than a single Mendelian gene with clear-cut dominant/recessive expression.

Characteristics: polygenic traits show continuous, quantitative variation (a bell-curve/normal distribution across a population) rather than discrete either/or categories -- classic anthropologically-relevant examples include human skin colour (governed by multiple genes including SLC24A5, MC1R and others), stature/height, and cranial/body-measurement traits studied in physical anthropology.

Significance: polygenic inheritance explains why traits like skin pigmentation vary continuously across populations (a gradient/cline related to UV-radiation adaptation -- Jablonski and Chaplin''s vitamin D/folate-protection hypothesis) rather than falling into discrete ''racial'' categories, providing a key genetic argument against biological race concepts, since polygenic clinal variation contradicts the idea of sharply bounded racial types. It also underlies modern genome-wide association studies (GWAS) used to study complex traits and disease susceptibility across human populations.', 'Skin colour as the standard anthropological example of polygenic inheritance should be explicitly named, along with its clinal/continuous distribution -- this directly links to the race-critique theme tested elsewhere in this paper (Q1c).', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q5(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('e178f22f-b32c-4c31-8aaa-4f9978a12068', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 16, 'B', '5(b)', 10, 150, 'Prehistoric significance of Rakhigarhi');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('e178f22f-b32c-4c31-8aaa-4f9978a12068', 'Rakhigarhi, in Haryana''s Ghaggar-Hakra plain, is among the largest known Indus Valley/Harappan Civilization sites, larger in extent than Mohenjo-daro in some estimates, with occupation spanning pre-Harappan through mature Harappan phases.

Significance: (i) demonstrates a long, continuous indigenous developmental sequence from early farming/pre-urban settlement to full urbanization, supporting an indigenous-origins model of Harappan civilization rather than one imposed externally; (ii) excavations (Vasant Shinde and team) revealed planned residential structures, drainage, craft-production areas (bead-making, pottery) and cemetery sites; (iii) ancient DNA extracted from a Rakhigarhi burial (published 2019) showed genetic ancestry lacking the ''Steppe pastoralist'' component associated with later Indo-Aryan migration, informing the ongoing Aryan-migration/indigenous-Harappan debate and suggesting the Harappan gene pool contributed substantially to later South Asian populations independent of subsequent Steppe admixture; (iv) its scale and antiquity make it central evidence for reassessing the geographic core and chronological depth of the Indus Civilization beyond the Indus valley proper.', 'The 2019 ancient-DNA study finding no Steppe-ancestry component in the Rakhigarhi individual, and its relevance to the Aryan-migration debate, is the single most important and frequently-tested specific fact for this topic.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q5(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('136937a3-a650-439d-a346-7f45c8823390', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 17, 'B', '5(c)', 10, 150, 'Glottochronology');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('136937a3-a650-439d-a346-7f45c8823390', 'Glottochronology, developed by Morris Swadesh in the 1950s, is a linguistic method that estimates the time depth since two related languages diverged from a common ancestor, based on the rate of replacement of ''core vocabulary'' (basic, culturally-universal words like body parts, numerals, kinship terms -- the Swadesh list).

Method: assumes core vocabulary is replaced at a roughly constant statistical rate over time (analogous to radioactive decay); by measuring the percentage of shared cognates in the core-vocabulary lists of two languages, a formula estimates the number of centuries since their common ancestor language split.

Critique: the assumption of a constant, universal replacement rate has been strongly challenged -- actual rates vary by language, by contact intensity, and by socio-historical factors, making glottochronological date estimates often unreliable. Despite this, it remains historically important in historical linguistics and linguistic anthropology as an early quantitative attempt to date language divergence, complementing archaeological and genetic evidence in reconstructing population history (e.g., debates on Dravidian or Indo-Aryan language-family dispersal timelines in South Asia).', 'The Swadesh core-vocabulary-list mechanism must be named specifically, and the ''constant replacement rate'' assumption''s critique is essential -- an answer presenting glottochronology as unproblematically reliable is incomplete.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q5(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ac0a6fd6-7cc6-41e4-8c16-53ce6826f603', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 18, 'B', '5(d)', 10, 150, 'Menopausal symptoms');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ac0a6fd6-7cc6-41e4-8c16-53ce6826f603', 'Menopause is the permanent cessation of menstruation and reproductive capacity in women, typically occurring around 45-55 years, resulting from declining ovarian follicular activity and consequent drop in estrogen and progesterone production.

Symptoms: vasomotor symptoms (hot flushes, night sweats) are the most characteristic; others include irregular/cessation of menses, vaginal dryness and atrophy, sleep disturbance, mood changes (irritability, anxiety, depression), reduced bone density (osteoporosis risk due to estrogen loss), changes in lipid profile (increased cardiovascular risk), and cognitive/memory complaints in some women.

Anthropological relevance: cross-cultural studies (Margaret Lock''s comparative work on Japanese vs North American women) show significant variation in menopausal symptom experience and reporting across cultures, challenging a purely universal-biomedical model -- suggesting cultural framing, diet (soy-based diets and phytoestrogens in Japan), social status of older women, and expectations shape symptom expression, making menopause a productive case study in biocultural anthropology of women''s reproductive life-course transitions.', 'Margaret Lock''s cross-cultural (Japan vs North America) menopause research is the standard anthropological reference expected here, illustrating that symptom experience is not purely biological but biocultural.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q5(d). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('427afedb-6bec-45d2-9c6c-58bf8cad571c', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 19, 'B', '5(e)', 10, 150, 'William Ogburn and Cultural lag');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('427afedb-6bec-45d2-9c6c-58bf8cad571c', 'William F. Ogburn, an American sociologist, introduced the concept of ''cultural lag'' in Social Change (1922), distinguishing between material culture (technology, tools, techniques) and non-material/adaptive culture (norms, laws, values, institutions).

Core thesis: material culture tends to change faster than non-material culture, since technological innovation can occur relatively rapidly while social institutions, laws and values adapt more slowly -- the resulting gap between the two is ''cultural lag,'' producing social strain, maladjustment or disorganization until non-material culture eventually ''catches up.''

Examples: rapid advances in reproductive technology (IVF, surrogacy) outpacing corresponding legal/ethical frameworks; digital/social-media technology outpacing privacy law and social norms around online conduct; automobile technology historically preceding adequate traffic law and urban planning. In India, examples include information technology and digital-payment adoption outpacing cyber-law and digital-literacy adaptation, or reproductive technologies outpacing surrogacy regulation until the Surrogacy (Regulation) Act, 2021.

Significance: Ogburn''s concept remains a foundational tool in the sociology/anthropology of technology and social change for explaining why rapid technological societies often experience recurring institutional and normative catch-up problems.', 'A concrete, ideally contemporary (digital technology, biotechnology) example of the material/non-material culture gap is expected alongside the correct attribution and definition; Ogburn''s authorship (Social Change, 1922) should be stated explicitly.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q5(e). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ff048468-148d-4721-80bd-22a481980aa5', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 20, 'B', '6(a)', 20, 350, 'Critically discuss the controversies related to fieldwork of Bronislaw Malinowski and Margaret Mead.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ff048468-148d-4721-80bd-22a481980aa5', 'Introduction: Malinowski and Mead are foundational figures of modern ethnographic fieldwork, but both became central to major posthumous controversies that reshaped anthropology''s understanding of fieldwork objectivity, ethics and interpretation.

Malinowski''s controversy: Malinowski, based on fieldwork among the Trobriand Islanders (1915-1918), pioneered intensive participant observation (living among informants, learning the local language, long-term immersion) as codified in Argonauts of the Western Pacific (1922), establishing the discipline''s core methodological standard. However, the posthumous 1967 publication of his private field diary (A Diary in the Strict Sense of the Term) revealed intensely negative, racist and disparaging personal remarks about the Trobrianders he studied, alongside evidence of personal frustration, loneliness and sexual preoccupation during fieldwork -- starkly contradicting the empathetic, objective persona projected in his published ethnographies. This controversy sparked major disciplinary reflection on the gap between fieldworkers'' private attitudes and published ''scientific'' accounts, fuelling the broader reflexive turn in anthropology (questioning ethnographic authority, objectivity and the politics of representation, later developed by writers like Clifford and Marcus in Writing Culture).

Mead''s controversy: Margaret Mead''s Coming of Age in Samoa (1928) argued Samoan adolescence was relatively free of the storm-and-stress typical of American teenagers, supporting a culture-over-biology (nurture) argument against biological determinism regarding adolescent turmoil. Decades later, Derek Freeman''s Margaret Mead and Samoa (1983) fiercely challenged her findings, alleging Mead had been misled by informants (some later claimed to have joked/exaggerated about their sexual conduct) and that her fieldwork (brief, and complicated by her limited fluency and short duration) produced an inaccurate, ideologically-driven portrait to fit her mentor Boas''s cultural-determinist agenda. This ''Mead-Freeman controversy'' remains contested -- subsequent scholars have criticized Freeman''s own methodology and motives as equally biased, and no full resolution has been reached.

Critical assessment: both controversies expose fieldwork''s inherent vulnerability to researcher bias, informant unreliability, linguistic/cultural barriers, and the difficulty of verifying long-past ethnographic claims -- while also demonstrating anthropology''s capacity for internal self-correction and epistemological reflexivity.

Conclusion: the Malinowski diary and Mead-Freeman controversies jointly catalyzed anthropology''s shift toward reflexive, self-critical methodology, acknowledging that ethnographic ''truth'' is always mediated by the fieldworker''s position, biases and interpretive choices.', 'Both controversies must be treated -- naming the specific publications (Malinowski''s Diary, Freeman''s Margaret Mead and Samoa) and their consequence for the discipline''s reflexive turn is the expected depth; a purely biographical/gossip-level answer without connecting to methodological reflexivity will be marked incomplete.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q6(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('cfd8ac0f-d46c-4857-8699-6928d9820cad', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 21, 'B', '6(b)', 15, 250, 'Discuss the impact of globalization on the economic systems of indigenous communities.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('cfd8ac0f-d46c-4857-8699-6928d9820cad', 'Globalization -- the intensified worldwide flow of capital, goods, technology, labour and culture -- has profoundly restructured indigenous communities'' traditionally self-sufficient or reciprocity-based economic systems.

Negative impacts: (i) displacement from traditional livelihoods -- market penetration, land acquisition for mining/plantations/dams has alienated many indigenous communities (Dongria Kondh''s opposition to Vedanta''s Niyamgiri bauxite mining) from subsistence resources; (ii) erosion of reciprocity-based economies -- barter and gift-exchange systems (jajmani-linked tribal exchange) weaken as cash-market relations penetrate; (iii) dependency and debt -- integration into wage labour or cash-crop markets on unequal terms creates vulnerability to price fluctuation and indebtedness; (iv) loss of traditional ecological knowledge as younger generations migrate to urban wage labour.

Positive/adaptive impacts: (i) new market opportunities for indigenous crafts, forest produce (minor forest produce marketing under PESA/Forest Rights Act) and ecotourism generate cash income while sometimes reinforcing cultural identity as a marketable asset; (ii) government welfare/development schemes and improved connectivity have expanded access to education, healthcare and formal employment; (iii) some communities have successfully leveraged legal/political mobilization enabled by globalized information networks (Niyamgiri Supreme Court verdict recognizing Dongria Kondh''s community forest rights) to resist exploitative economic integration.

Conclusion: globalization''s economic impact on indigenous communities is deeply uneven -- generating both displacement/dependency and new adaptive opportunities -- with outcomes shaped heavily by the strength of legal protections (Forest Rights Act, PESA) and community mobilization capacity.', 'A balanced answer requires both the exploitation/displacement narrative (mining, land acquisition) and the adaptive/opportunity narrative (ecotourism, minor forest produce markets, legal mobilization); citing the Niyamgiri/Dongria Kondh case is a strong, frequently-expected Indian example.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q6(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('9d004b1e-98f5-4b1b-a91b-9977a4a11f76', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 22, 'B', '6(c)', 15, 250, 'Describe the practical applications of DNA technology in the current scenario.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('9d004b1e-98f5-4b1b-a91b-9977a4a11f76', 'DNA technology -- encompassing sequencing, PCR amplification, and comparative genomic analysis -- has wide practical applications across forensic, medical, population and applied anthropology.

Forensic applications: DNA fingerprinting/profiling for individual identification in criminal investigations, paternity disputes, and mass-disaster victim identification (using STR profiling of nuclear DNA, or mitochondrial DNA for degraded remains).

Medical/health applications: genetic screening for hereditary disease risk (sickle-cell anaemia and thalassemia screening, both significant in Indian tribal and general populations), prenatal genetic diagnosis, personalized medicine based on individual genomic profiles, and gene therapy research.

Population and evolutionary anthropology: ancient DNA (aDNA) analysis of archaeological remains (e.g., the Rakhigarhi genome study) to reconstruct migration history, population admixture and the peopling of regions; molecular anthropology comparing mitochondrial DNA (maternal lineage) and Y-chromosome (paternal lineage) haplogroups across populations to map human dispersal and admixture (Out-of-Africa migration routes, South Asian population-history studies).

Agricultural and other applications: genetically modified crops, DNA barcoding for species identification (biodiversity conservation, combating wildlife trafficking), and genetic-ancestry testing services.

Ethical/anthropological dimension: DNA technology''s use in tracing indigenous ancestry and migration raises important questions about informed consent, genetic privacy, and the potential misuse of genetic data to reinforce essentialist race/ethnicity narratives -- issues actively debated in the anthropology of science and biotechnology.

Conclusion: DNA technology''s applications now span forensic, medical, evolutionary and agricultural domains, while simultaneously raising the ethical questions central to contemporary anthropological engagement with genomic science.', 'Naming a specific Indian application (Rakhigarhi aDNA study, sickle-cell/thalassemia screening in tribal populations) alongside the standard forensic-DNA-fingerprinting example gives the answer the expected anthropological grounding rather than a purely biology-textbook listing.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q6(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('4792e3e4-eb6a-4a88-8aa9-9d6b8d438a42', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 23, 'B', '7(a)', 20, 350, 'Describe various methods of qualitative data analysis. Highlight some popular computer softwares used in qualitative analysis.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('4792e3e4-eb6a-4a88-8aa9-9d6b8d438a42', 'Introduction: qualitative data analysis in anthropology involves systematically interpreting non-numerical data -- field notes, interview transcripts, photographs, documents -- to identify patterns, themes and meanings central to ethnographic understanding.

Major methods: (i) Thematic analysis -- identifying, coding and categorizing recurring themes/patterns across data (open coding, axial coding, selective coding as in Grounded Theory, Glaser and Strauss); (ii) Content analysis -- systematically categorizing textual/visual content, sometimes with quantifiable frequency counts of themes or terms (qualitative or quantitative content analysis); (iii) Narrative analysis -- examining how informants structure and tell their life-stories/experiences, focusing on sequence, plot and meaning-making; (iv) Discourse analysis -- analyzing language use, power relations and ideology embedded in speech/text (Foucauldian discourse analysis); (v) Case study method -- in-depth, holistic analysis of a single case (individual, family, community) to generate rich contextual understanding; (vi) Comparative/cross-cultural method -- systematically comparing patterns across multiple ethnographic cases (Human Relations Area Files-based comparison); (vii) Grounded theory -- building theory inductively from the data itself rather than testing a pre-existing hypothesis, through constant comparison and iterative coding.

Popular computer software: NVivo -- widely used for coding, thematic organization, and visualizing relationships across large qualitative datasets (interview transcripts, field notes); ATLAS.ti -- similar coding and network-visualization capacities, popular for grounded-theory-style analysis; MAXQDA -- combines qualitative coding with some quantitative/mixed-methods integration; Dedoose -- web-based, supports mixed-methods analysis including qualitative coding alongside quantitative data.

Significance and limitations: these software tools primarily assist in organizing, coding and retrieving large volumes of qualitative data efficiently, but the interpretive analytical work itself remains the researcher''s task -- software organizes rather than substitutes for anthropological interpretation, and over-reliance on software-driven coding schemes can risk flattening the contextual richness central to ethnographic method.

Conclusion: qualitative analysis in anthropology spans thematic, narrative, discourse, comparative and grounded-theory methods, increasingly supported (but not replaced) by specialized software like NVivo and ATLAS.ti that streamline coding and organization of large ethnographic datasets.', 'Naming specific software (NVivo, ATLAS.ti, MAXQDA) is explicitly demanded by the question and is often the most under-answered part; grounded theory (Glaser and Strauss) as a named method is expected content for the analysis-methods half.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q7(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('877fcf8f-4808-477a-9cc7-b7ea343952fb', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 24, 'B', '7(b)', 15, 250, 'What assumptions must be met for a population to be in genetic equilibrium? Explain the importance of genetic equilibrium.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('877fcf8f-4808-477a-9cc7-b7ea343952fb', 'Genetic (Hardy-Weinberg) equilibrium describes a theoretical state in which allele and genotype frequencies in a population remain constant across generations, absent evolutionary forces -- serving as the null-hypothesis baseline against which real evolutionary change is measured.

Required assumptions: (i) large (effectively infinite) population size, to prevent random genetic drift; (ii) random mating (panmixia), with no assortative mating preferences; (iii) no mutation altering allele frequencies; (iv) no migration/gene flow into or out of the population; (v) no natural selection (all genotypes have equal survival and reproductive fitness); (vi) non-overlapping generations (in the standard model).

Hardy-Weinberg equation: for a gene with two alleles (frequencies p and q, where p+q=1), genotype frequencies at equilibrium follow p^2 + 2pq + q^2 = 1 (homozygous dominant, heterozygous, homozygous recessive respectively).

Importance: (i) provides a mathematical baseline/null model -- any deviation from expected Hardy-Weinberg genotype frequencies signals that one or more real evolutionary forces (selection, drift, migration, mutation, non-random mating) are actively operating in that population, making it an essential diagnostic tool in population genetics; (ii) used in anthropological/medical genetics to estimate carrier frequencies for recessive genetic disorders (e.g., estimating sickle-cell trait carrier frequency in a population from observed disease incidence); (iii) underpins forensic DNA-profiling statistical calculations; (iv) foundational teaching model connecting Mendelian genetics to population-level evolutionary theory.

Conclusion: genetic equilibrium''s assumptions, though rarely fully met in real populations, provide the indispensable theoretical yardstick for detecting and quantifying real evolutionary change.', 'All five/six assumptions must be listed completely and the Hardy-Weinberg equation itself should be stated; the ''null hypothesis/baseline for detecting evolution'' framing is the key conceptual point for the importance half.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q7(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c230f554-d869-40ef-86f2-a6201659cca1', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 25, 'B', '7(c)', 15, 250, 'Discuss political and methodological aspects of national character studies. Elucidate the contemporary relevance of such studies.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c230f554-d869-40ef-86f2-a6201659cca1', 'National character studies -- an approach within the ''Culture and Personality'' school (Ruth Benedict, Margaret Mead, Geoffrey Gorer, Abram Kardiner) -- attempted to characterize a nation''s or ethnic group''s typical/modal personality traits as shaped by shared childhood-rearing practices and cultural patterning, notably in Benedict''s The Chrysanthemum and the Sword (Japanese national character, WWII-era) and Gorer''s studies of Russian/American character (including the controversial ''swaddling hypothesis'' linking Russian character to infant swaddling practices).

Political aspects: these studies were substantially driven by wartime and Cold War political needs -- understanding an adversary or ally nation''s likely behaviour without direct fieldwork access (Benedict''s Japan study was conducted at a distance, from documents/interviews with Japanese-Americans, for US wartime policy purposes), making national-character research an instrument of state intelligence/propaganda as much as academic anthropology.

Methodological critiques: (i) ''modal personality'' assumes unwarranted homogeneity within large, diverse national populations, ignoring internal class, regional, ethnic and individual variation; (ii) heavy reliance on psychoanalytic frameworks (childhood-rearing determinism, as in the swaddling hypothesis) lacked rigorous empirical verification; (iii) at-a-distance culture study (without direct fieldwork) compromised ethnographic validity; (iv) risk of stereotyping and essentializing entire nations, uncomfortably close to earlier racial-typological thinking the discipline had otherwise moved past.

Contemporary relevance: despite these flaws, the underlying insight -- that cultural patterns of socialization influence widely-shared behavioural tendencies -- persists in modified form in cross-cultural psychology, area studies, and political-culture research on national institutions and civic behaviour, now conducted with more rigorous, locally-grounded and statistically-representative methods rather than sweeping modal-personality claims.

Conclusion: national character studies exemplify both anthropology''s practical utility to political/military need and the methodological caution required when generalizing culture-personality claims across entire nations.', 'Benedict''s Chrysanthemum and the Sword and its wartime political context is the essential named example; the methodological critique (homogeneity assumption, at-a-distance study, stereotyping risk) must be explicit, not just descriptive praise of the approach.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q7(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('23f020e1-b6ac-42c0-a947-e4c13f366352', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 26, 'B', '8(a)', 20, 350, 'Critically examine Arjun Appadurai''s conceptualization of global cultural economy.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('23f020e1-b6ac-42c0-a947-e4c13f366352', 'Introduction: Arjun Appadurai, in ''Disjuncture and Difference in the Global Cultural Economy'' (1990, later in Modernity at Large, 1996), proposed a framework for understanding globalization''s cultural dimension as operating through complex, overlapping, non-isomorphic global flows, moving beyond older centre-periphery or cultural-imperialism models.

The five ''-scapes'': Appadurai identifies five dimensions of global cultural flow: (i) Ethnoscapes -- flows of people (tourists, migrants, refugees, guest workers) across national boundaries, reshaping communities'' composition and identity; (ii) Mediascapes -- flows of images and information via global media (television, film, internet), shaping imagined worlds and aspirations even among those who never physically migrate; (iii) Technoscapes -- flows of technology (mechanical and informational) across borders, often driven by multinational capital and uneven configurations of state and corporate power; (iv) Financescapes -- flows of global capital, currency markets and investment, moving at speeds and volumes that can rapidly destabilize national economies; (v) Ideoscapes -- flows of political ideas and ideologies (democracy, human rights, freedom), often derived from Enlightenment-linked master-narratives, but reinterpreted differently across contexts.

Disjuncture and difference: Appadurai''s central argument is that these five -scapes move at different speeds and along different, non-aligned trajectories -- disjunctures -- rejecting simplistic models where economic globalization (financescapes) is assumed to determine cultural globalization (mediascapes/ideoscapes) in lockstep, or where globalization is simply Westernization/homogenization imposed uniformly.

Imagination as social practice: Appadurai emphasizes that globalized media flows have made ''imagination'' a collective social practice -- ordinary people worldwide now imagine alternative lives, identities and possibilities partly shaped by globally circulating images, altering local identity formation and aspiration.

Critical examination: strengths include moving beyond crude homogenization/cultural-imperialism theses to capture globalization''s genuinely complex, multi-directional and locally-reinterpreted character, and anticipating digital-era phenomena (social media ethnoscapes/mediascapes) well ahead of their emergence. Critiques include the framework''s abstractness and difficulty in empirical operationalization (the -scapes are suggestive metaphors rather than precisely measurable categories), and insufficient attention to enduring structural power asymmetries (Western/corporate dominance over global media and financial flows) that some critics argue persist despite the model''s emphasis on disjuncture and local agency.

Conclusion: Appadurai''s -scapes framework remains one of the most influential anthropological contributions to globalization theory, valuably complicating simpler homogenization narratives, even as its abstractness and under-attention to persistent power asymmetries invite continued critical refinement.', 'All five -scapes must be named and briefly explained -- omitting even one is a common way marks are lost; the ''disjuncture'' concept (non-aligned movement of the five flows) is the specific conceptual core the question tests, not just a list of globalization''s dimensions.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q8(a). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('411ed5f7-5136-4f12-949f-c75d472496d8', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 27, 'B', '8(b)', 15, 250, 'Describe the causes of structural abnormalities of chromosomes with suitable examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('411ed5f7-5136-4f12-949f-c75d472496d8', 'Structural chromosomal abnormalities arise from breakage and faulty rearrangement of chromosome segments, distinct from numerical abnormalities (aneuploidy, e.g., extra/missing whole chromosomes).

Causes: chromosome breakage can result from errors during DNA replication or recombination (crossing-over) in meiosis/mitosis, exposure to ionizing radiation, certain chemical mutagens, viral infections, or spontaneous replication errors; when broken segments rejoin incorrectly, various structural rearrangements result.

Types with examples: (i) Deletion -- loss of a chromosome segment (Cri-du-chat syndrome, from partial deletion of chromosome 5''s short arm, causing a characteristic cat-like infant cry and intellectual disability); (ii) Duplication -- a segment repeated, increasing gene dosage; (iii) Translocation -- segment transferred between non-homologous chromosomes, either reciprocal (segments exchanged between two chromosomes) or Robertsonian (fusion of two acrocentric chromosomes, e.g., some cases of Down syndrome arise from a Robertsonian translocation involving chromosome 21 rather than simple trisomy); (iv) Inversion -- a segment breaks and reattaches in reversed orientation, which can be paracentric (not involving the centromere) or pericentric (spanning the centromere), potentially disrupting gene function at breakpoints and affecting fertility through problems in meiotic pairing; (v) Ring chromosome -- both ends of a chromosome break off and the remaining piece fuses into a ring, often causing developmental abnormalities depending on which genes are lost.

Significance: these rearrangements underlie numerous genetic syndromes and are studied via karyotyping and cytogenetic analysis, relevant to genetic counselling and to physical anthropology''s broader study of human chromosomal variation and its population-level distribution.', 'Each named type (deletion, duplication, translocation, inversion) should carry a concrete syndrome/example (Cri-du-chat for deletion, Robertsonian translocation Down syndrome variant) rather than purely abstract definitions.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q8(b). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('36cd5e2f-9972-4d0f-b8ca-fb445aaeab10', '26f0fff0-7815-4ef7-93ac-24c0dd52c80c', 28, 'B', '8(c)', 15, 250, 'Critically discuss A.L. Kroeber''s contribution to kinship studies.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('36cd5e2f-9972-4d0f-b8ca-fb445aaeab10', 'Alfred L. Kroeber, an influential American anthropologist (Boas''s student), made a foundational early contribution to kinship studies through his 1909 paper ''Classificatory Systems of Relationship,'' widely regarded as launching systematic anthropological kinship terminology analysis.

Core contribution: Kroeber argued that kinship terminologies (the actual words a language uses for relatives) are not simply a direct reflection of biological/genealogical relationships or of a society''s social-structural organization (contra later British structural-functionalist views, notably Radcliffe-Brown, who linked terminology closely to social structure and behaviour patterns like the avunculate). Instead, Kroeber proposed that kinship terms are primarily linguistic/psychological categories, classifying relatives according to a limited set of underlying criteria -- such as generation, lineal vs collateral distinction, gender of relative, gender of speaker, and age relative to speaker (older/younger) -- treating kinship terminology essentially as a special case of linguistic classification rather than a direct map of jural/structural rights and obligations.

Critical assessment: this psychological/linguistic emphasis was influential in stimulating rigorous componential analysis of kinship terms (later formalized by Floyd Lounsbury and Ward Goodenough using componential/feature analysis) and shifted kinship studies toward systematic, comparative cross-cultural classification. However, Kroeber''s approach was criticized, notably by Radcliffe-Brown, for underplaying the genuine sociological significance of kinship terms -- critics argued terminology often does correlate meaningfully with actual social behaviour, rights and obligations (e.g., joking/avoidance relationships correlating with specific terminological categories), meaning Kroeber''s purely categorical/linguistic framing risked stripping kinship terms of their social-structural content.

Conclusion: Kroeber''s 1909 paper remains a foundational, if contested, starting point for the entire subsequent field of kinship-terminology analysis, catalyzing both componential-analysis methodology and the enduring Kroeber-versus-Radcliffe-Brown debate on whether kinship terms are primarily linguistic categories or sociological structures.', 'Naming the 1909 paper and explicitly contrasting Kroeber''s linguistic/psychological view against Radcliffe-Brown''s structural-functionalist view is the expected core content -- a purely descriptive ''Kroeber studied kinship'' answer without this specific theoretical contrast will not earn full marks.', 'UPSC CSE Mains 2023, Anthropology Optional Paper I, Section B, Q8(c). Verified directly against a PDF text extraction (pdftotext -layout) of the official bilingual (Hindi/English) printed question paper, hosted as Anthropology_Vikas-Gupta.pdf on pwonlyias.com (pwonlyias.com/wp-content/uploads/2023/09/Anthropology_Vikas-Gupta.pdf). Cross-checked against Edukemy''s full question-paper transcription (edukemy.com) and Anthroholic''s bilingual reproduction of the note-writing questions (anthroholic.com).');
